     invariant on lock with (val, guard, ghost_id) is (v: usize, g: RwPerms<T>) {
         let has_writer_bit: bool = (v & WRITER) != 0;
         let has_upgrade_bit: bool = (v & UPGRADEABLE_READER) != 0;
         let has_max_reader_bit: bool = (v & MAX_READER) != 0;
